window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/natureza_2022.js"]=[{"title":"Radicais oxidantes degradam o contaminante","steps":["O persulfato gera radicais capazes de atacar o tricloroeteno.","O esquema mostra sua transformação em produtos oxigenados, com alteração dos estados de oxidação.","A classifica a remediação como oxirredução: há transferência de elétrons e oxidação do contaminante, não mera troca de grupo funcional."],"alternatives":{"A":"A transformação do contaminante por agentes oxidantes envolve variações de número de oxidação.","B":"Não se trata simplesmente de substituir um átomo conservando o restante da estrutura.","C":"O mecanismo não depende de retirar o contaminante como sólido insolúvel.","D":"Não é uma reação de eliminação de água como processo principal.","E":"Não se descreve apenas o consumo recíproco de um ácido e uma base."},"takeaway":"Presença de espécies radicalares oxidantes e degradação de moléculas apontam para processos de oxirredução.","key":"natureza:N766","area":"natureza","year":2022,"number":91,"answer":"A","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As duas doenças dependem de vetores","steps":["A filariose é causada por nematódeos e pode ser transmitida por mosquitos.","A leishmaniose é causada por protozoários e transmitida por flebotomíneos.","D identifica uma prevenção comum: controlar os respectivos vetores, sem supor que sejam o mesmo inseto."],"alternatives":{"A":"Incineração de lixo não é a medida comum específica das cadeias de transmissão.","B":"Saneamento pode ajudar em contextos determinados, mas não é a medida direta comum pedida.","C":"Vermífugo não previne uma protozoose como a leishmaniose e não substitui controle vetorial.","D":"Reduzir o contato e a população dos vetores interfere na transmissão das duas doenças.","E":"A transmissão não depende de comer carne vermelha crua ou malcozida."},"takeaway":"Para comparar profilaxias, identifique primeiro agente etiológico e forma de transmissão de cada doença.","key":"natureza:N272","area":"natureza","year":2022,"number":92,"answer":"D","subject":"Biologia","topic":"Zoologia e parasitologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Use a potência elétrica total e o rendimento","steps":["O parque tem duas usinas de 75 MW, totalizando 150 milhões de watts.","Cada metro quadrado fornece 1 500 × 0,20 = 300 W elétricos nas condições dadas.","A área é 150 000 000 / 300 = 500 000 m²: B. A energia anual não é necessária para essa estimativa."],"alternatives":{"A":"Um milhão de metros quadrados corresponderia a 300 MW nessas condições, o dobro da potência.","B":"Quinhentos mil metros quadrados a 300 W por metro quadrado fornecem os 150 MW.","C":"Este valor atende a somente uma das duas usinas de 75 MW.","D":"Cem mil metros quadrados forneceriam apenas 30 MW.","E":"Vinte mil metros quadrados forneceriam apenas 6 MW."},"takeaway":"Em rendimento, potência útil = eficiência × irradiância × área; não misture potência instantânea e energia anual.","key":"natureza:N421","area":"natureza","year":2022,"number":93,"answer":"B","subject":"Física","topic":"Trabalho, energia e potência","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cianeto acidificado e açúcar oxidado trazem riscos diferentes","steps":["No conjunto 1, H⁺ reage com CN⁻, formando HCN, substância extremamente tóxica e volátil.","No conjunto 2, o ácido nítrico concentrado atua como oxidante sobre a matéria orgânica.","A reúne liberação de gás tóxico e reação oxidativa forte. É análise de risco: nunca execute essas misturas."],"alternatives":{"A":"A acidificação libera HCN e o ácido nítrico pode oxidar fortemente a sacarose.","B":"A sequência está invertida: a primeira mistura não tem a oxidação como processo principal.","C":"O perigo característico do primeiro conjunto é a formação de HCN, não apenas de um sal.","D":"A segunda mistura é caracterizada pela oxidação da matéria orgânica, não pela simples liberação de gás oxidante.","E":"Nenhuma das duas descrições corresponde corretamente aos riscos principais dos conjuntos."},"takeaway":"Substâncias conhecidas isoladamente podem formar produtos letais quando misturadas: compatibilidade química é essencial.","key":"natureza:N800","area":"natureza","year":2022,"number":94,"answer":"A","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[2],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A bússola tangencia as linhas circulares do campo","steps":["Coloque o polegar da mão direita no sentido da corrente, para cima.","Os outros dedos indicam campo circular, anti-horário visto de cima.","A extremidade norte de cada agulha deve acompanhar esse sentido na tangente local; apenas D satisfaz as três posições."],"alternatives":{"A":"A orientação exibida não acompanha as tangentes e o sentido circular em todas as posições.","B":"A configuração não mantém as três extremidades norte no sentido dado pela mão direita.","C":"Há agulhas com sentido incompatível com a circulação exigida para a corrente ascendente.","D":"As três agulhas tangenciam as linhas e orientam seus polos norte conforme a mão direita.","E":"Tangenciar o círculo não basta: os polos norte também precisam apontar no sentido correto, o que a opção não cumpre."},"takeaway":"A bússola aponta ao longo do campo no ponto; não aponta necessariamente para o fio nem para cima.","key":"natureza:N588","area":"natureza","year":2022,"number":95,"answer":"D","subject":"Física","topic":"Magnetismo e indução","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Duas baterias em série fornecem corrente de 24 mA","steps":["Pela tabela, a parada respiratória está na faixa de 20 a 100 mA.","Com pele molhada de 1 000 Ω, duas baterias somadas dão I = 24/1 000 = 0,024 A = 24 mA.","A apresenta a associação em série com tensões que se somam. O modelo é do exercício, não uma indicação de tensão segura."],"alternatives":{"A":"Os 24 V da série aditiva produzem 24 mA no modelo de resistência informado.","B":"As baterias aparecem em oposição, e suas tensões iguais não se somam entre A e B.","C":"A ligação em paralelo mantém 12 V, correspondendo a 12 mA, abaixo da faixa pedida.","D":"A oposição de fontes iguais não fornece os 24 V necessários entre os terminais.","E":"A ligação com polaridades opostas no paralelo é inadequada e não representa a série aditiva de 24 V."},"takeaway":"Choque depende de corrente, percurso, tempo e condições corporais; números de uma tabela didática não garantem segurança.","key":"natureza:N330","area":"natureza","year":2022,"number":96,"answer":"A","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A diferença de massa permite enriquecimento por centrifugação","steps":["Os dois hexafluoretos contêm isótopos de urânio de massas diferentes.","Em uma centrífuga, a rotação permite pequena separação entre as distribuições dos gases de massas distintas.","B explora esse contraste físico, que precisa ser ampliado em etapas sucessivas."],"alternatives":{"A":"Peneiras comuns não distinguem moléculas quase idênticas por essa pequena diferença isotópica.","B":"A rotação explora diferenças de massa entre os hexafluoretos de urânio isotopicamente distintos.","C":"A química dos isótopos é muito semelhante; não é a diferença de solubilidade indicada.","D":"A destilação comum não é a alternativa de separação por massa solicitada.","E":"Os isótopos não passam a ter propriedades magnéticas suficientemente diferentes apenas por essa massa."},"takeaway":"Isótopos têm o mesmo número atômico e química muito semelhante, mas massas distintas permitem processos físicos específicos.","key":"natureza:N855","area":"natureza","year":2022,"number":97,"answer":"B","subject":"Química","topic":"Estrutura atômica e periodicidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A cópia funcional precisa ser expressa pela célula","steps":["O vetor viral leva uma cópia normal de RPE65 às células-alvo.","A sequência pode ser transcrita e traduzida para produzir a enzima funcional.","E descreve expressão gênica; inserir uma cópia não significa reescrever o código genético ou reparar obrigatoriamente o alelo original."],"alternatives":{"A":"Código genético é a correspondência entre códons e aminoácidos, não a sequência defeituosa de um gene.","B":"A terapia não depende de modificar o RNA que compõe os ribossomos.","C":"Não se induzem mutações aleatórias na esperança de obter uma alteração benéfica.","D":"O produto leva material genético; a proteína precisa ser produzida pelas células.","E":"A expressão da cópia funcional permite produzir a enzima normal na célula-alvo."},"takeaway":"Diferencie gene, código genético, expressão e mutação: são conceitos relacionados, mas não intercambiáveis.","key":"natureza:N106","area":"natureza","year":2022,"number":98,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma exótica invasora pode substituir a vegetação nativa","steps":["A questão trata do potencial de uma espécie introduzida reduzir a diversidade.","Ao ocupar espaço e disputar recursos, ela pode limitar o estabelecimento de plantas nativas.","A descreve essa substituição parcial da flora. Nem toda espécie exótica é automaticamente invasora."],"alternatives":{"A":"A expansão sobre áreas nativas pode reduzir populações e diversidade da flora original.","B":"Não se demonstrou que disputar os frutos elimine necessariamente os animais perdedores.","C":"Mais possibilidades de relações não explica diretamente a redução pedida.","D":"Uma população não pode manter indefinidamente crescimento acima dos recursos disponíveis.","E":"Facilitar a dispersão de nativas não corresponde ao mecanismo central de perda de biodiversidade."},"takeaway":"Exótica descreve origem; invasora descreve expansão com impactos. Avalie o mecanismo ecológico concreto.","key":"natureza:N013","area":"natureza","year":2022,"number":99,"answer":"A","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A queda horizontal permite calcular a velocidade de saída","steps":["Na queda de 1 m, 1 = 10t²/2, logo t² = 0,2 s².","Como o alcance é 3 m, v² = 3²/t² = 45 m²/s².","Lançada verticalmente com a mesma velocidade, a água sobe h = v²/(2g) = 45/20 = 2,25 m acima da saída: B."],"alternatives":{"A":"Dividir o alcance horizontal por dois não fornece a altura máxima.","B":"A velocidade deduzida do lançamento horizontal leva a 2,25 m acima da saída.","C":"Somar alturas ou alcances sem a relação energética não reproduz o resultado.","D":"Este valor equivale a v²/g e deixa de incluir o fator dois.","E":"A altura pedida não é a soma direta de medidas do experimento."},"takeaway":"Movimentos horizontal e vertical compartilham o tempo na queda; a altura do lançamento vertical usa a velocidade encontrada.","key":"natureza:N382","area":"natureza","year":2022,"number":100,"answer":"B","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compare sacarose restante, não apenas a inicial","steps":["A perda percentual em dez horas é 50% vezes a concentração numérica de microrganismos.","As concentrações restantes são 13×0,65=8,45; 18×0,60=10,8; 16×0,70=11,2; 14×0,75=10,5; 17×0,55=9,35 g/L.","O maior valor é 11,2 g/L, da RB92: C."],"alternatives":{"A":"A RB72 conserva 8,45 g/L, menos que a amostra escolhida.","B":"A RB84 começa com mais açúcar, mas resta com 10,8 g/L.","C":"A RB92 combina teor inicial e deterioração para conservar 11,2 g/L.","D":"A menor concentração de microrganismos não basta: a SP79 conserva 10,5 g/L.","E":"A maior deterioração reduz a SP80 a 9,35 g/L."},"takeaway":"Quando o percentual de perda varia, calcule o valor final de cada opção antes de ordenar.","key":"natureza:N746","area":"natureza","year":2022,"number":101,"answer":"C","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"RNA viral precisa virar DNA complementar antes da PCR","steps":["O SARS-CoV-2 tem genoma de RNA.","A PCR convencional amplifica DNA, usando uma DNA polimerase.","É necessária transcrição reversa para gerar cDNA a partir do RNA viral: E, base da RT-PCR."],"alternatives":{"A":"Concentrar RNA não muda o tipo de molécula que a PCR amplifica.","B":"Anticorpos são alvos de exames sorológicos, não da amplificação genética.","C":"Não é preciso cultivar vírus infectantes para executar a etapa molecular descrita.","D":"Purificar a amostra pode integrar o preparo, mas não resolve a incompatibilidade RNA/DNA.","E":"A transcriptase reversa fornece o DNA complementar que poderá ser amplificado."},"takeaway":"RT significa transcrição reversa; não confunda com o monitoramento em tempo real de algumas modalidades de PCR.","key":"natureza:N107","area":"natureza","year":2022,"number":102,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Peso no centro de massa; contato apenas na ponta","steps":["O peso atua verticalmente para baixo no centro de massa.","A normal é perpendicular ao piso na ponta apoiada; o atrito é horizontal nesse mesmo contato.","A força aplicada acompanha a muleta e empurra a base para a esquerda; o atrito se opõe a essa tendência, para a direita. E reúne tudo isso."],"alternatives":{"A":"Mostra a força aplicada vertical e o peso no contato, contrariando as condições e o centro de massa.","B":"Erra a direção de F e aplica a normal no centro de massa, além do sentido de atrito.","C":"Mantém F paralela, mas aplica o peso na ponta inferior, em vez do centro de massa.","D":"Aplica a normal no centro de massa e inverte o sentido do atrito no apoio.","E":"O peso age no CM; normal e atrito agem no apoio, com atrito para a direita."},"takeaway":"No diagrama de corpo livre, verifique quatro coisas: força, ponto de aplicação, direção e sentido.","key":"natureza:N383","area":"natureza","year":2022,"number":103,"answer":"E","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mais hemácias ampliam a capacidade de transportar oxigênio","steps":["A eritropoietina estimula a produção de células vermelhas do sangue.","As hemácias contêm hemoglobina, que transporta a maior parte do oxigênio sanguíneo.","E identifica o efeito diretamente associado ao doping descrito; isso não torna o uso seguro ou permitido."],"alternatives":{"A":"O mecanismo principal não é acelerar diretamente os batimentos cardíacos.","B":"A produção de hemácias não aumenta diretamente o volume pulmonar.","C":"O hormônio citado não atua como agente anabolizante muscular direto.","D":"O benefício descrito está ligado ao suprimento de oxigênio, não à ativação anaeróbica direta.","E":"A elevação da capacidade de transporte de oxigênio pode sustentar maior desempenho aeróbico."},"takeaway":"Eritropoiese é produção de hemácias; não confunda com ventilação pulmonar ou crescimento da musculatura.","key":"natureza:N194","area":"natureza","year":2022,"number":104,"answer":"E","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Retornar aumenta o impulso; parar dissipa mais energia","steps":["Para mesmo tempo de colisão, força média depende da variação da quantidade de movimento.","Nos pneus, a inversão de sentido faz essa variação ter módulo m(v inicial + v retorno), maior que m v inicial nos blocos.","Nos blocos o carro termina parado e perde toda a energia cinética inicial; nos pneus conserva parte dela no retorno. Portanto A."],"alternatives":{"A":"Pneus exigem maior variação de momento; blocos retiram mais energia cinética do carro.","B":"Inverte as duas comparações: retorno amplia o impulso e conserva energia cinética final.","C":"Os blocos têm menor impulso e as energias dissipadas não são iguais.","D":"A força nos pneus é maior, mas a energia cinética perdida é maior nos blocos.","E":"A perda de energia nos blocos é maior, porém a força média é menor que nos pneus."},"takeaway":"Impulso usa velocidade vetorial; energia cinética usa o quadrado do módulo. Voltar não equivale a simplesmente parar.","key":"natureza:N384","area":"natureza","year":2022,"number":105,"answer":"A","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compare o pH com o pKa de cada grupo","steps":["Entre pH 5 e 7, o meio está acima de 1,8: a carboxila fica predominantemente COO⁻.","O meio está abaixo de 7,9 e de 10,5: predominam NH₃⁺ e SH, respectivamente.","A forma com COO⁻, NH₃⁺ e SH é C, uma espécie com cargas de sinais opostos e carga líquida nula."],"alternatives":{"A":"Mostra tiol desprotonado e amino neutro, contrariando os valores de pKa no intervalo.","B":"Mantém COOH e desprotona SH, invertendo as tendências previstas.","C":"Reúne carboxilato, grupo amínio e tiol, formas predominantes no pH informado.","D":"Embora traga NH₃⁺, conserva COOH e representa o enxofre como S⁻ inadequadamente.","E":"Acerta NH₃⁺ e SH, mas a carboxila já deve estar predominantemente desprotonada."},"takeaway":"Para um par ácido/base, pH acima do pKa favorece a forma desprotonada; abaixo, a protonada.","key":"natureza:N801","area":"natureza","year":2022,"number":106,"answer":"C","subject":"Química","topic":"Equilíbrio químico e pH","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O ácido catalisa a quebra das ligações glicosídicas","steps":["O esquema começa com participação de H⁺ e termina regenerando essa espécie.","A protonação oferece um caminho reacional de menor energia de ativação para a hidrólise.","C identifica a função catalítica de aumentar a velocidade, sem mudar a constante de equilíbrio na mesma temperatura."],"alternatives":{"A":"A dissolução pode afetar uma reação, mas não explica a regeneração de H⁺ no mecanismo.","B":"Um catalisador acelera ida e volta; não desloca sozinho o equilíbrio final.","C":"A catálise ácida torna mais rápida a conversão dos polissacarídeos.","D":"A constante termodinâmica de equilíbrio não muda apenas pela presença do catalisador.","E":"A interação decisiva é a participação catalítica na protonação e clivagem, não apenas uma ligação de hidrogênio."},"takeaway":"Identifique catalisadores no mecanismo: são consumidos em uma etapa e regenerados em outra.","key":"natureza:N701","area":"natureza","year":2022,"number":107,"answer":"C","subject":"Química","topic":"Reações orgânicas e polímeros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cada mol de ácido consome dois de NaOH","steps":["A base consumida corresponde a 0,10 × 0,0080 = 8,0×10⁻⁴ mol.","Pela proporção 1:2, a alíquota contém 4,0×10⁻⁴ mol de ácido, isto é, 0,060 g.","Em 0,025 L, a concentração é 0,060/0,025 = 2,4 g/L: B."],"alternatives":{"A":"Não resulta da proporção estequiométrica nem da massa na alíquota de 25 mL.","B":"O consumo de base equivale a 0,060 g de ácido em 25 mL, ou 2,4 g/L.","C":"Este valor não corresponde ao volume e à proporção de dois NaOH por ácido.","D":"Este é o resultado de supor indevidamente proporção de um mol de ácido por mol de base.","E":"Este valor dobra novamente o erro de desprezar a estequiometria correta."},"takeaway":"Converta mL para L e use os coeficientes da reação antes de passar de mol a grama.","key":"natureza:N747","area":"natureza","year":2022,"number":108,"answer":"B","subject":"Química","topic":"Soluções e concentração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Quarenta dias correspondem a cinco meias-vidas","steps":["A tabela mostra redução de 12 para 6 microgramas em oito dias.","Em quarenta dias passam 40/8 = 5 meias-vidas.","A massa restante é 12/(2⁵) = 0,375 micrograma, mais próxima de 0,4: D."],"alternatives":{"A":"Dividir a massa por cinco períodos não representa decaimento exponencial.","B":"1,5 micrograma corresponderia a três meias-vidas, ou 24 dias.","C":"0,75 micrograma, arredondado para 0,8, corresponderia a quatro meias-vidas.","D":"Cinco reduções sucessivas à metade deixam 0,375 micrograma, próximo de 0,4.","E":"Cerca de 0,2 micrograma corresponderia a seis meias-vidas."},"takeaway":"Meia-vida descreve divisão repetida pela metade, não retirada de uma massa fixa a cada intervalo.","key":"natureza:N195","area":"natureza","year":2022,"number":109,"answer":"D","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Estratégias reprodutivas diferentes podem favorecer a continuidade","steps":["A primeira espécie produz muitos gametas e não acompanha os descendentes.","Outras produzem menos, mas oferecem proteção espacial ou cuidado parental.","D reconhece diferentes estratégias de sucesso reprodutivo; isso não é garantia de sobrevivência de todo descendente."],"alternatives":{"A":"Os exemplos não isolam influência feminina como explicação geral dos comportamentos.","B":"A espécie 1 se desenvolve sem acompanhamento dos pais, refutando a necessidade universal.","C":"Não há uma escala de espécies mais e menos evoluídas.","D":"Número de descendentes e investimento em proteção podem se combinar de maneiras distintas.","E":"O texto não demonstra mudança individual induzida pelo ambiente na produção de gametas."},"takeaway":"Evolução não é uma escada de progresso: estratégias distintas podem funcionar em contextos diferentes.","key":"natureza:N229","area":"natureza","year":2022,"number":110,"answer":"D","subject":"Biologia","topic":"Evolução e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O máximo em janeiro indica verão no hemisfério sul","steps":["A barra de janeiro é a maior, e a de julho é a menor.","Em condições ensolaradas comparáveis, isso é compatível com maior disponibilidade solar no verão austral.","A aponta a região do Trópico de Capricórnio; nos polos haveria sazonalidade muito mais extrema, inclusive noite polar."],"alternatives":{"A":"A região tropical sul tem verão próximo de janeiro e inverno próximo de julho.","B":"No Trópico de Câncer o padrão anual principal estaria invertido.","C":"O Polo Norte tem noite polar em parte do período de inverno boreal, não máximo em janeiro.","D":"No Polo Sul, parte do período teria ausência de Sol, o que não condiz com todas as barras positivas.","E":"No Equador a variação de duração do dia é pequena e não explica esse padrão de máximo e mínimo."},"takeaway":"Inclinação do eixo, hemisfério e duração da insolação explicam a sazonalidade; não use a distância ao Sol como causa das estações.","key":"natureza:N596","area":"natureza","year":2022,"number":111,"answer":"A","subject":"Física","topic":"Gravitação e astronomia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A tração máxima é dividida entre dois segmentos","steps":["Ao sair da horizontal e chegar ao ponto mais baixo, a criança desce uma altura igual ao comprimento L.","Conservação da energia dá v² = 2gL; no ponto inferior, 2T − mg = mv²/L, então 2T = 3mg.","Com m=24 kg, T=360 N por segmento. Acrescentando 25%, a ruptura exigida é 1,25×360 = 450 N: D."],"alternatives":{"A":"120 N é metade do peso em repouso, sem a aceleração centrípeta nem a margem.","B":"300 N acrescenta margem ao peso, mas não considera corretamente o esforço dinâmico.","C":"360 N é a tensão máxima calculada em cada segmento, ainda sem a margem.","D":"A margem de segurança eleva os 360 N por segmento a 450 N.","E":"900 N soma os valores dos dois segmentos, mas a especificação é a tensão em cada corda."},"takeaway":"No ponto inferior do balanço há aceleração centrípeta: a soma das trações precisa superar o peso.","key":"natureza:N385","area":"natureza","year":2022,"number":112,"answer":"D","subject":"Física","topic":"Mecânica: cinemática e dinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O filme cerâmico funciona como barreira","steps":["O ferro corrói em contato com agentes do ambiente, como oxigênio e água.","O revestimento é formado por óxidos de zircônio e alumínio depositados sobre ele.","D identifica a barreira que reduz o contato; não se trata de um metal sacrificial que será oxidado no lugar do ferro."],"alternatives":{"A":"Não se instala um metal redutor eletricamente ligado para proteção catódica.","B":"Zircônia e alumina já são óxidos; a proposta não é oxidar um metal de sacrifício.","C":"A camada descrita não é formada pelo próprio óxido de ferro.","D":"O filme protege ao dificultar que água e agente oxidante alcancem a superfície metálica.","E":"Não se descreve revestimento com zinco metálico ou galvanização equivalente."},"takeaway":"Revestimento de barreira e proteção eletroquímica são mecanismos diferentes, embora ambos possam reduzir corrosão.","key":"natureza:N767","area":"natureza","year":2022,"number":113,"answer":"D","subject":"Química","topic":"Eletroquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A água entra e dilui o pigmento vacuolar","steps":["O meio hipotônico apresenta menor concentração de solutos que o interior celular.","Por osmose, há entrada de água, expansão do vacúolo e aumento de turgescência.","C relaciona o aumento do volume à diluição do pigmento; a parede limita a expansão e ajuda a evitar lise."],"alternatives":{"A":"A entrada de água não implica fragmentação do vacúolo.","B":"Na célula vegetal, a parede oferece resistência ao aumento de volume.","C":"Mais água no vacúolo aumenta seu volume e reduz a concentração do pigmento.","D":"Não se prevê quebra normal da parede como resultado dessa condição.","E":"Murchamento e perda de água seriam esperados em meio hipertônico, não hipotônico."},"takeaway":"Osmose altera o volume de solvente; se o pigmento permanece, maior volume significa menor concentração.","key":"natureza:N158","area":"natureza","year":2022,"number":114,"answer":"C","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Compare a capacidade térmica de volumes iguais","steps":["Para um mesmo calor Q, ΔT = Q/(mc) e m = ρV.","Com volumes iguais, ΔT concreto/ΔT água = (ρ água × c água)/(ρ concreto × c concreto).","A razão é (1 000×4,2)/(2 500×0,8) = 4 200/2 000 = 2,1: B."],"alternatives":{"A":"A razão não é um porque as capacidades térmicas dos volumes são distintas.","B":"O produto densidade por calor específico da água é 2,1 vezes o do concreto.","C":"2,5 é a razão entre densidades, sem levar em conta os calores específicos.","D":"Cerca de 5,3 compara apenas calores específicos e ignora as massas diferentes.","E":"Este valor não combina corretamente densidade e calor específico para volumes iguais."},"takeaway":"Mesmo volume não significa mesma massa: use a densidade antes de comparar aquecimento.","key":"natureza:N502","area":"natureza","year":2022,"number":115,"answer":"B","subject":"Física","topic":"Termologia e termodinâmica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A potência máxima exige disjuntor de 30 A no modelo","steps":["Na posição superquente com 3 L/min, passam 3 000 g em 60 s, ou 50 g/s.","A potência térmica é 50×4,2×30 = 6 300 W; a corrente é 6 300/220 ≈ 28,64 A.","O múltiplo de 5 A imediatamente superior é 30 A: B. Este é o modelo do exercício, não um projeto de instalação elétrica."],"alternatives":{"A":"Sessenta amperes excede o múltiplo imediatamente superior solicitado.","B":"Trinta amperes é o primeiro múltiplo de cinco acima de aproximadamente 28,64 A.","C":"Vinte amperes é inferior à corrente na condição superquente.","D":"Dez amperes não atende à corrente máxima calculada.","E":"Cinco amperes também é inferior ao necessário mesmo para a operação máxima."},"takeaway":"Em chuveiros, relacione potência elétrica a vazão mássica, calor específico e variação de temperatura.","key":"natureza:N331","area":"natureza","year":2022,"number":116,"answer":"B","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Carbonato com ácido libera dióxido de carbono","steps":["O mármore contém carbonato de cálcio.","A reação é CaCO₃ + 2 HCl → CaCl₂ + H₂O + CO₂.","O gás observado é CO₂, alternativa C; aquecimento não significa que o gás produzido seja combustível."],"alternatives":{"A":"Hidrogênio pode surgir em reação de certos metais com ácidos, mas não é o produto do carbonato.","B":"Não há decomposição que produza oxigênio molecular como gás principal.","C":"A protonação do carbonato resulta em água e dióxido de carbono.","D":"Monóxido de carbono não é o produto da reação ácido-carbonato descrita.","E":"O cloro permanece majoritariamente como cloreto, não é convertido em Cl₂ nesse processo."},"takeaway":"Reconheça a reação característica de carbonatos com ácidos: sal, água e liberação de CO₂.","key":"natureza:N825","area":"natureza","year":2022,"number":117,"answer":"C","subject":"Química","topic":"Cinética química","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A redução de testosterona acompanha a desmasculinização","steps":["No gráfico, machos-controle têm concentração alta; fêmeas-controle, baixa.","Os machos expostos apresentam redução para valores próximos aos das fêmeas.","A testosterona, ligada ao desenvolvimento de caracteres masculinos, corresponde a C. O gráfico descreve esse estudo em sapos, não uma conclusão clínica sobre humanos."],"alternatives":{"A":"A associação com desmasculinização e a maior concentração nos machos-controle indicam outro hormônio.","B":"Feromônios são sinais químicos entre indivíduos, não o hormônio sexual sanguíneo descrito.","C":"A queda de testosterona é compatível com as alterações de caracteres masculinos observadas.","D":"Somatotrofina está principalmente ligada a crescimento, não ao padrão sexual específico do item.","E":"FSH participa da função reprodutiva, mas não é o andrógeno que explica os caracteres destacados."},"takeaway":"Integre padrão do gráfico e função fisiológica: uma curva isolada não identifica automaticamente qualquer hormônio.","key":"natureza:N196","area":"natureza","year":2022,"number":118,"answer":"C","subject":"Biologia","topic":"Fisiologia humana e saúde","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A forma tridimensional determina a atividade da enzima","steps":["Os ensaios são independentes, com temperatura como variável controlada.","A atividade cresce até 15 °C nos pontos medidos e depois diminui.","Mudanças conformacionais alteram o sítio ativo e ajudam a explicar a queda: E. Não se deve concluir que toda temperatura maior acelera indefinidamente a enzima."],"alternatives":{"A":"O enunciado mantém as demais condições; não fornece variação de pH.","B":"Não é necessário supor aumento da barreira energética de uma enzima estruturalmente intacta.","C":"Catalisadores não são consumidos estequiometricamente a cada transformação.","D":"Os ensaios independentes não descrevem uma única reação acompanhada enquanto acaba o substrato.","E":"A temperatura pode alterar a conformação e a eficiência do sítio ativo, inclusive por desnaturação."},"takeaway":"Uma curva enzimática combina efeito cinético da temperatura e estabilidade da proteína; confira também o desenho do experimento.","key":"natureza:N159","area":"natureza","year":2022,"number":120,"answer":"E","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O alvo que diferencia fungos e bactérias é o microtúbulo","steps":["Fungos são eucariontes e segregam cromátides por um fuso de microtúbulos.","Bactérias não fazem mitose nem têm esse fuso; dividem-se por outros mecanismos.","O antimicrobiano 2, alternativa B, é o alvo diferencial na tabela hipotética. Isso não garante ausência de efeitos sobre células humanas."],"alternatives":{"A":"Fungos e bactérias possuem ribossomos e realizam síntese proteica.","B":"O alvo descrito participa da mitose dos fungos e não da divisão bacteriana.","C":"Ambos possuem membrana plasmática com fosfolipídios, de modo que o alvo não é seletivo aqui.","D":"Os dois grupos precisam de timina para produzir seu DNA.","E":"Ambos sintetizam RNA e dependem de uracila para isso."},"takeaway":"Compare estruturas e processos dos organismos; seletividade contra bactérias não equivale a segurança para o paciente.","key":"natureza:N296","area":"natureza","year":2022,"number":121,"answer":"B","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Modular a coagulação pode evitar um trombo","steps":["A molécula interfere na coagulação sanguínea.","Trombos são coágulos formados nos vasos e podem obstruir o fluxo.","A é a aplicação potencial, inclusive em certos AVCs isquêmicos. AVC hemorrágico é diferente, e o item não autoriza uso clínico indiscriminado."],"alternatives":{"A":"Impedir trombos pode reduzir obstruções vasculares em condições nas quais a coagulação participa.","B":"Uma substância anticoagulante não repõe hemácias nem corrige anemia por perda de sangue.","C":"Urticária envolve mecanismos alérgicos, não é o alvo de coagulação descrito.","D":"Aumento de linfonodos se relaciona à resposta imune, sem aplicação direta demonstrada aqui.","E":"Não se mostrou uma ação primária sobre os mecanismos de controle da pressão."},"takeaway":"Aplicação potencial de uma molécula não é prescrição; diferencie trombose, hemorragia, anemia e alergia.","key":"natureza:N108","area":"natureza","year":2022,"number":122,"answer":"A","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mesma massa central mantém a atração nas órbitas planetárias","steps":["No modelo, a massa do novo corpo é igual à massa solar.","Na distância dos planetas, a atração gravitacional depende dessa massa e da distância, não do tamanho do horizonte de eventos.","Sem alteração das posições e velocidades iniciais, as órbitas permanecem: E. A iluminação e as condições de vida mudariam, mas isso não é o comando."],"alternatives":{"A":"Não aparece uma perda de energia orbital que obrigue espiralar para dentro.","B":"A substituição por massa igual não introduz uma perturbação aleatória.","C":"Buraco negro não suga automaticamente objetos que já orbitam longe do horizonte.","D":"Na idealização do item, não há aumento de massa ou mudança orbital que justifique maior precessão.","E":"Massa central, posição e velocidade mantidas preservam a dinâmica orbital considerada."},"takeaway":"Não confunda força gravitacional externa com a possibilidade de escapar de dentro do horizonte de eventos.","key":"natureza:N597","area":"natureza","year":2022,"number":123,"answer":"E","subject":"Física","topic":"Gravitação e astronomia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O ozônio pode oxidar também componentes dos organismos","steps":["A mesma reatividade que contribui para descontaminar pode danificar tecidos.","O ozônio é um agente oxidante forte e pode reagir com moléculas biológicas.","B identifica o risco químico, sem endossar sua pulverização sobre pessoas."],"alternatives":{"A":"A ação principal não é apenas acelerar uma reação mantendo-se inalterado.","B":"A capacidade de oxidar componentes celulares explica tanto parte da ação sanitizante quanto a toxicidade.","C":"Um agente redutor doa elétrons; não é a caracterização pedida para o ozônio.","D":"A toxicidade em discussão não decorre principalmente de doar prótons como ácido.","E":"O problema também não se explica por uma ação básica de neutralização."},"takeaway":"Ser capaz de matar microrganismos não torna uma substância segura para contato direto com seres humanos.","key":"natureza:N461","area":"natureza","year":2022,"number":124,"answer":"B","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A proporção de células com cada X ativo muda a intensidade do fenótipo","steps":["A inativação de um X ocorre cedo e é mantida nas linhagens celulares.","Mulheres heterozigotas podem ter proporções diferentes de células expressando o alelo normal ou o alterado em cada tecido.","E identifica expressividade variável: diferença na intensidade de manifestação associada a esse mosaico."],"alternatives":{"A":"Pleiotropia é um gene influenciar diferentes características, não o efeito de proporções celulares distintas.","B":"Inativação epigenética de um X não significa criar uma mutação na sequência do gene.","C":"O exemplo não exige interação entre genes diferentes para produzir o caráter.","D":"Penetrância trata da presença ou ausência de manifestação; o item enfatiza a variação de expressão pelo mosaico.","E":"A quantidade e a distribuição de células com cada X ativo podem modificar o grau de manifestação."},"takeaway":"Diferencie penetrância, se aparece, de expressividade, como e com que intensidade aparece.","key":"natureza:N109","area":"natureza","year":2022,"number":125,"answer":"E","subject":"Biologia","topic":"Genética e biotecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os flocos são retirados principalmente por decantação","steps":["A coagulação favorece a agregação das partículas que estavam suspensas.","Os flocos formados podem sedimentar pela ação da gravidade.","B identifica a etapa de retirada de grande parte desses sólidos; a filtração complementa a remoção do que permanece."],"alternatives":{"A":"A coagulação prepara a separação ao desestabilizar partículas, sem retirá-las por si.","B":"Na decantação, os flocos sedimentam e podem ser separados da água clarificada.","C":"Filtros retêm material restante, mas a retirada da maior parte dos flocos ocorre antes.","D":"A desinfecção visa inativar agentes biológicos, não sedimentar sólidos.","E":"A fluoretação ajusta fluoreto e não é uma etapa de separação de partículas."},"takeaway":"Em tratamento de água, diferencie formar flocos, separá-los, reter resíduos e desinfetar.","key":"natureza:N626","area":"natureza","year":2022,"number":126,"answer":"B","subject":"Química","topic":"Química ambiental e separação de misturas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Desacoplar o gradiente da síntese de ATP libera calor","steps":["A cadeia respiratória estabelece um gradiente de prótons na membrana interna mitocondrial.","A termogenina oferece uma via de retorno que não passa pela ATP sintase.","Isso desacopla parte da fosforilação oxidativa e dissipa energia como calor: E. Não significa que a cadeia pare necessariamente de consumir oxigênio."],"alternatives":{"A":"A glicólise ocorre no citosol e não usa o gradiente de prótons mitocondrial.","B":"A fermentação lática não utiliza a ATP sintase mitocondrial.","C":"O ciclo cítrico fornece transportadores reduzidos, mas não é a etapa diretamente desacoplada.","D":"Converter piruvato em acetil-CoA não usa o retorno de prótons pela ATP sintase.","E":"A interferência atinge o acoplamento entre gradiente e produção de ATP na fosforilação oxidativa."},"takeaway":"Desacoplamento pode manter a oxidação e reduzir a produção de ATP por energia liberada, aumentando a termogênese.","key":"natureza:N160","area":"natureza","year":2022,"number":127,"answer":"E","subject":"Biologia","topic":"Citologia e bioquímica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ordene o quociente entre tensão e corrente","steps":["A analogia define resistência pela lei de Ohm: R = U/I.","Calculando: R₁ = 510/4 = 127,5; R₂ = 608/4 = 152; R₃ = 575/3 ≈ 191,7, nas unidades do modelo.","A ordem crescente é 1, 2, 3, alternativa A. Não basta ordenar as tensões isoladamente."],"alternatives":{"A":"Os quocientes crescem de 127,5 para 152 e depois para aproximadamente 191,7.","B":"A rota 3 tem resistência maior que a 2, apesar de apresentar menor tensão.","C":"A resistência da rota 1 é menor, e não maior, que a da rota 2.","D":"A menor corrente da rota 3 eleva seu quociente; ela não é a primeira.","E":"A sequência apresentada é decrescente, oposta ao critério do aplicativo."},"takeaway":"Em analogias físicas, use a relação definida pelo enunciado e conserve o significado de cada grandeza.","key":"natureza:N333","area":"natureza","year":2022,"number":128,"answer":"A","subject":"Física","topic":"Eletricidade e circuitos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O meio ácido favorece a protonação da amônia","steps":["pH menor significa maior disponibilidade de H⁺.","No equilíbrio NH₃ + H⁺ ⇌ NH₄⁺, adicionar prótons favorece o íon amônio.","C é a espécie favorecida por essa relação ácido-base; o comando não pede toda a resposta ecológica do ciclo à chuva ácida."],"alternatives":{"A":"O nitrogênio molecular não é produzido simplesmente pela protonação direta da amônia.","B":"A amônia é consumida na formação de sua espécie protonada em meio mais ácido.","C":"NH₄⁺ resulta da captura de um próton por NH₃ e é favorecido em menor pH.","D":"Nitrito não é a espécie do par ácido-base apresentado na inferência central.","E":"Nitrato envolve outros processos do ciclo e não é o produto da protonação da amônia."},"takeaway":"Mudança de pH pode ser analisada localmente por um equilíbrio químico, sem atribuir toda transformação biológica ao mesmo mecanismo.","key":"natureza:N014","area":"natureza","year":2022,"number":129,"answer":"C","subject":"Biologia","topic":"Ecologia e impactos ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Bastonetes mais sensíveis respondem com menos luz","steps":["O texto associa bastonetes à quantidade de fótons incidentes.","Maior sensibilidade permite resposta com menor quantidade de luz.","C corresponde a enxergar melhor em ambientes mal iluminados; percepção de cores envolve principalmente os cones."],"alternatives":{"A":"Daltonismo envolve principalmente diferenças nos sistemas de percepção cromática, não esse aumento de sensibilidade.","B":"Detectar menos fótons não amplia automaticamente as frequências do espectro visível.","C":"Maior sensibilidade permite perceber sinais em condições de baixa iluminação.","D":"A alternativa inverte a consequência: maior sensibilidade reduz a quantidade mínima necessária.","E":"A distinção de cores não é a função central dos bastonetes destacada no item."},"takeaway":"Intensidade luminosa e frequência são variáveis distintas: pouca luz não é uma nova cor.","key":"natureza:N543","area":"natureza","year":2022,"number":130,"answer":"C","subject":"Física","topic":"Óptica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As estruturas apresentadas compartilham um anel benzênico","steps":["Ignore inicialmente os nomes e os cheiros e compare as fórmulas.","Todas apresentam o ciclo aromático de seis carbonos representado como anel benzênico.","C identifica a unidade comum desta família apresentada. Existem outros sistemas aromáticos: o item não define toda aromaticidade possível pelo benzeno."],"alternatives":{"A":"Substituintes e ramificações não são o critério eletrônico característico da família.","B":"Ligações múltiplas também existem em moléculas não aromáticas.","C":"O anel benzênico comum às fórmulas é a unidade estrutural pedida.","D":"Oxigênio aparece nas substâncias, mas compostos oxigenados não são necessariamente aromáticos.","E":"Carbono assimétrico não é requisito de aromaticidade e não caracteriza o conjunto."},"takeaway":"Aromaticidade é conceito eletrônico; odor agradável não é um teste estrutural e nem todo aromático é derivado do benzeno.","key":"natureza:N679","area":"natureza","year":2022,"number":131,"answer":"C","subject":"Química","topic":"Química orgânica: funções e propriedades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Bactéria e vírus disputam recursos no mesmo hospedeiro","steps":["Wolbachia vive dentro das células do mosquito.","O vírus também precisa dessas células e de recursos para se multiplicar.","D corresponde à competição no hospedeiro descrita pelo texto; não se trata de criar mosquitos transgênicos ou estéreis."],"alternatives":{"A":"O enunciado não descreve a bactéria ingerindo vírus como uma presa.","B":"A reprodução dos mosquitos é importante para disseminar a bactéria; não se propõe esterilização.","C":"Hospedar uma bactéria não equivale a alterar a sequência genética do mosquito.","D":"O uso de recursos celulares compartilhados limita a multiplicação viral na interpretação proposta.","E":"Não se insere no genoma bacteriano material genético do vírus para esse mecanismo."},"takeaway":"Controle biológico pode reduzir a capacidade de transmitir uma doença sem eliminar ou esterilizar todos os vetores.","key":"natureza:N297","area":"natureza","year":2022,"number":132,"answer":"D","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O antígeno tumoral passa a ser reconhecido pela resposta adaptativa","steps":["O protozoário modificado produz moléculas associadas ao tumor.","Ao responder ao vetor, o organismo entra em contato com esses antígenos e desenvolve reconhecimento específico.","D identifica apresentação de antígeno específico, permitindo direcionar a resposta às células que o expressam. Trata-se do experimento narrado, não de uma vacina clínica já garantida."],"alternatives":{"A":"O objetivo é reconhecer antígenos tumorais, não induzir ataque indiscriminado a tecidos saudáveis.","B":"Hipersensibilidade é uma resposta lesiva exagerada e não o mecanismo específico solicitado.","C":"A especificidade do reconhecimento não é explicada apenas por defesa inata.","D":"A exposição ao antígeno tumoral promove resposta que reconhece a mesma molécula nas células-alvo.","E":"Suprimir inflamação não explica a destruição das células portadoras do antígeno."},"takeaway":"Uma plataforma vacinal pode ensinar o sistema imune a reconhecer uma molécula de outro alvo, inclusive tumoral.","key":"natureza:N298","area":"natureza","year":2022,"number":133,"answer":"D","subject":"Biologia","topic":"Microbiologia e imunologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Use o atraso entre os sinais, não o tempo absoluto do gráfico","steps":["Picos correspondentes aparecem separados por cerca de 12 s; o sinal chega antes pela água.","Os tempos de propagação são L/340 no ar e L/1 540 na água; a diferença é 12.","Logo L(1/340 − 1/1 540)=12, dando L = 12×340×1 540/1 200 = 5 236 m, aproximadamente 5 240 m: D."],"alternatives":{"A":"Usar tempos absolutos do registro confunde o início da gravação com a emissão do som.","B":"O tempo de chegada contado desde ligar o aparelho não é o tempo de propagação.","C":"Multiplicar o atraso pela diferença entre velocidades não resolve a diferença entre L/v.","D":"A diferença dos inversos das velocidades leva a cerca de 5,24 km.","E":"Cem metros dariam atraso de aproximadamente 0,23 s, não de 12 s."},"takeaway":"Quando o instante de emissão é desconhecido, subtraia tempos de chegada de sinais que percorreram a mesma distância.","key":"natureza:N462","area":"natureza","year":2022,"number":134,"answer":"D","subject":"Física","topic":"Ondulatória e acústica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A água muda a direção da luz que entra pela garrafa","steps":["A garrafa atravessa o telhado e recebe luz solar.","Ao atravessar interfaces entre meios de índices diferentes, a luz sofre refração e se distribui pelo ambiente.","E é o fenômeno central. A abertura muito maior que o comprimento de onda afasta a difração como explicação predominante."],"alternatives":{"A":"A dimensão da abertura é muito maior que o comprimento de onda, desfavorecendo essa explicação principal.","B":"Absorver luz retira energia luminosa; não explica conduzi-la e distribuí-la para dentro.","C":"Não há seleção de direção de oscilação da luz como princípio do dispositivo.","D":"Reflexões podem existir, mas não são o mecanismo principal de mudança de meio destacado.","E":"A passagem entre ar, plástico e água modifica a propagação e redireciona a luz incidente."},"takeaway":"Refração redistribui luz solar existente: a garrafa não cria energia nem substitui iluminação noturna sem fonte externa.","key":"natureza:N544","area":"natureza","year":2022,"number":135,"answer":"E","subject":"Física","topic":"Óptica","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D2_CD7.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/natureza/gab_2022.pdf","sha256":"1b4b0cd0978bfc6c862d9631c4f8a5c25091938d09acfd2bd8c8b510764cb118","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/natureza/prova_2022.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
